package com.hrm.employee;

import android.os.Handler;
import android.os.Looper;
import android.graphics.Color;
import android.graphics.Typeface;
import android.view.View;
import android.widget.*;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import com.google.android.material.dialog.MaterialAlertDialogBuilder;
import org.json.*;
import java.util.concurrent.*;

/** Foreground polling only. No device push/background delivery is claimed. */
public final class MobileNotifications {
 private final AppCompatActivity activity;private final HrmApi api;private final HrmApplication session;private final TextView badge;
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService executor=Executors.newSingleThreadExecutor();
 private boolean active=false,countBusy=false,listBusy=false,writing=false,unreadOnly=false;private int generation=0,page=0;private Long snapshot=null;private AlertDialog dialog;private LinearLayout content;
 private final Runnable poll=new Runnable(){public void run(){if(!active)return;refreshCount();if(dialog!=null&&dialog.isShowing())load();handler.postDelayed(this,15000);}};
 public MobileNotifications(AppCompatActivity activity,HrmApi api,HrmApplication session,View trigger,TextView badge){this.activity=activity;this.api=api;this.session=session;this.badge=badge;trigger.setOnClickListener(v->open());}
 public void start(){if(active)return;active=true;handler.post(poll);}
 public void stop(){active=false;++generation;handler.removeCallbacks(poll);countBusy=false;listBusy=false;writing=false;if(dialog!=null)dialog.dismiss();dialog=null;}
 public void destroy(){stop();executor.shutdownNow();}
 private boolean current(int g){return active&&g==generation&&!activity.isDestroyed();}
 private void refreshCount(){if(countBusy)return;countBusy=true;int g=generation;String token=session.token();executor.execute(()->{try{JSONObject response=api.get("/api/notifications/unread-count",token);activity.runOnUiThread(()->{if(!current(g))return;long count=response.optLong("unreadCount");badge.setText(count>99?"99+":String.valueOf(count));badge.setVisibility(count>0?View.VISIBLE:View.GONE);badge.setContentDescription(count+" thông báo chưa đọc");});}catch(Exception ignored){}finally{activity.runOnUiThread(()->{if(current(g))countBusy=false;});}});}
 private TextView text(String message,boolean bold){TextView t=new TextView(activity);t.setText(message);t.setTextSize(14);t.setTextColor(0xff163d5c);t.setPadding(10,10,10,10);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 private Button button(String label,Runnable action){Button b=new Button(activity);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->action.run());return b;}
 public void open(){if(!active||writing)return;if(dialog!=null&&dialog.isShowing())return;page=0;snapshot=null;content=new LinearLayout(activity);content.setOrientation(LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(activity);scroll.addView(content);dialog=new MaterialAlertDialogBuilder(activity).setTitle("Thông báo").setView(scroll).setNegativeButton("Đóng",null).create();dialog.setOnDismissListener(d->{dialog=null;content=null;});dialog.show();load();}
 private void load(){if(!active||listBusy||writing||content==null)return;listBusy=true;int g=generation;String token=session.token();String path="/api/notifications?page="+page+"&size=10"+(unreadOnly?"&read=false":"")+(page>0&&snapshot!=null?"&snapshotId="+snapshot:"");executor.execute(()->{try{JSONObject result=api.get(path,token);activity.runOnUiThread(()->{if(!current(g)||content==null)return;listBusy=false;draw(result);});}catch(Exception e){activity.runOnUiThread(()->{if(!current(g)||content==null)return;listBusy=false;content.removeAllViews();content.addView(text(HrmApi.message(e),false));content.addView(button("Thử lại",this::load));});}});}
 private void draw(JSONObject result){if(content==null)return;content.removeAllViews();snapshot=result.optLong("snapshotId");long count=result.optLong("unreadCount");badge.setText(count>99?"99+":String.valueOf(count));badge.setVisibility(count>0?View.VISIBLE:View.GONE);
  LinearLayout filters=new LinearLayout(activity);filters.addView(button(unreadOnly?"Tất cả":"✓ Tất cả",()->{unreadOnly=false;page=0;snapshot=null;load();}));filters.addView(button(unreadOnly?"✓ Chưa đọc":"Chưa đọc",()->{unreadOnly=true;page=0;snapshot=null;load();}));content.addView(filters);
  Button all=button("Đánh dấu tất cả đã đọc",()->{if(snapshot!=null)write("/api/notifications/read-all",json("throughId",snapshot),null);});all.setEnabled(count>0&&!writing);content.addView(all);
  JSONArray rows=result.optJSONArray("items");if(rows==null||rows.length()==0)content.addView(text("Không có thông báo phù hợp.",false));
  else for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;boolean unread=!row.optBoolean("isRead");Button item=button((unread?"● Chưa đọc · ":"Đã đọc · ")+row.optString("title")+"\n"+row.optString("message")+"\n"+format(row.optString("createdAt")),()->select(row));item.setTextAlignment(View.TEXT_ALIGNMENT_VIEW_START);item.setBackgroundTintList(android.content.res.ColorStateList.valueOf(unread?0xffe8f1ff:Color.WHITE));item.setTypeface(null,unread?Typeface.BOLD:Typeface.NORMAL);content.addView(item);}
  LinearLayout navigation=new LinearLayout(activity);Button prev=button("Trước",()->{page--;load();});prev.setEnabled(page>0);navigation.addView(prev);navigation.addView(text((result.optInt("totalPages")>0?page+1:0)+" / "+result.optInt("totalPages"),false));Button next=button("Sau",()->{page++;load();});next.setEnabled(page+1<result.optInt("totalPages"));navigation.addView(next);content.addView(navigation);
 }
 private void select(JSONObject row){if(writing)return;writing=true;int g=generation;String token=session.token();executor.execute(()->{try{JSONObject target=api.get("/api/notifications/"+row.optLong("id")+"/target",token);api.send("/api/notifications/"+row.optLong("id")+"/read","PUT",token,new JSONObject());activity.runOnUiThread(()->{if(!current(g))return;writing=false;page=0;snapshot=null;load();refreshCount();JSONObject d=target.optJSONObject("detail");if(d==null)return;String message="Trạng thái: "+status(d.optString("status"))+"\nNgày gửi: "+format(d.optString("submittedAt"))+"\nLý do: "+d.optString("reason", "—");for(String field:new String[]{"proposedStart","proposedEnd","receivedAt","processedAt","decisionReason","rejectionReason","requestedLastWorkingDate","approvedLastWorkingDate"})if(!d.isNull(field)&&!d.optString(field).isEmpty())message+="\n"+label(field)+": "+format(d.optString(field));new MaterialAlertDialogBuilder(activity).setTitle(d.optString("requestCode","Chi tiết")).setMessage(message).setPositiveButton("Đóng",null).show();});}catch(Exception e){activity.runOnUiThread(()->{if(!current(g))return;writing=false;new MaterialAlertDialogBuilder(activity).setTitle("Không mở được thông báo").setMessage(HrmApi.message(e)).setPositiveButton("Đóng",null).show();});}});}
 private void write(String path,JSONObject body,JSONObject unused){if(writing)return;writing=true;int g=generation;String token=session.token();executor.execute(()->{try{api.send(path,"PUT",token,body);activity.runOnUiThread(()->{if(!current(g))return;writing=false;page=0;snapshot=null;load();refreshCount();});}catch(Exception e){activity.runOnUiThread(()->{if(!current(g))return;writing=false;Toast.makeText(activity,HrmApi.message(e),Toast.LENGTH_LONG).show();});}});}
 private JSONObject json(String key,long value){JSONObject result=new JSONObject();try{result.put(key,value);}catch(JSONException e){throw new IllegalArgumentException(e);}return result;}
 private String status(String value){switch(value){case "CHO_XU_LY":return "Chờ xử lý";case "DANG_XU_LY":return "Đã tiếp nhận";case "DA_CHAP_NHAN":return "Đã chấp thuận";case "CHO_DUYET":return "Chờ duyệt";case "DA_DUYET":return "Đã duyệt";case "TU_CHOI":return "Từ chối";default:return value;}}
 private String label(String field){switch(field){case "proposedStart":return "Giờ vào đề nghị";case "proposedEnd":return "Giờ ra đề nghị";case "receivedAt":return "Tiếp nhận";case "processedAt":return "Xử lý";case "decisionReason":return "Kết quả xử lý";case "rejectionReason":return "Lý do từ chối";case "requestedLastWorkingDate":return "Ngày làm cuối đề nghị";default:return "Ngày làm cuối được duyệt";}}
 private String format(String value){try{if(value.endsWith("Z"))return java.time.Instant.parse(value).atZone(java.time.ZoneId.of("Asia/Ho_Chi_Minh")).format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"));if(value.length()>10)return java.time.LocalDateTime.parse(value).format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"));}catch(Exception ignored){}return value;}
}
